    "sourceName": "The Guardian",
    "sourceUrl": "https://www.theguardian.com/tv-and-radio/2026/nov/05/rory-kinnear-father-roy-death",
    "image": "assets/images/in-dept/image8.jpg",
    "imageCaption": "Master papermaker pressing fine sheets of handmade Do paper from wild rhamnoneuron bark.",
    "video": "https://www.youtube.com/embed/8t07V5aCcME",
